import re
p=open('src/page.html').read()
import os
W='src/words'
parts=['_runtime.js','challenge_millie.js','challenge_kristan.js','english.js','french.js','_after.js']
open('words.js','w').write('/* Generated by src/build.py from src/words/*.js. Edit those files, not this one. */\n'+'\n'.join(open(os.path.join(W,f)).read() for f in parts))
p=p.replace('<script>\n/*__ENGINE__*/\n/*__PROGRESS__*/\n/*__AVATAR__*/\n</script>','<script src="engine.js"></script>\n<script src="words.js"></script>\n<script src="progress.js"></script>\n<script src="avatar.js"></script>')
assert '__ENGINE__' not in p
i=p.index('</style>')+len('</style>')
head,body=p[:i],p[i:]
html='<!doctype html>\n<html lang="en-GB">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<meta name="theme-color" content="#080b2b">\n<meta name="robots" content="noindex,nofollow">\n<link rel="icon" type="image/png" sizes="32x32" href="/icons/favicon-32.png">\n<link rel="apple-touch-icon" sizes="180x180" href="/icons/apple-touch-icon.png">\n<link rel="manifest" href="/manifest.webmanifest">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-title" content="Hollyend">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="application-name" content="Hollyend">\n<style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>\n'+head+'\n</head>\n<body>'+body+'\n</body>\n</html>\n'
open('index.html','w').write(html)
print(len(html))
